EN={1:'gochamaze',2:'kazuawazu',3:'sabitsuki',4:'suppaniga'}
for id,kid,topic,stage,t,ch,ex,ce,src in [
 ('P4-S01','P-HEN-KAGAKU',U1,1,'ゴチャマゼ・ツボが中身をかきまぜている！「氷が溶けて水になるのは、化学変化だよ！」 ツボが力を溜めている！',['氷→水は状態が変わるだけの物理変化','化学変化','酸化'],'物質そのものは変わらないので物理変化。',['正しい。','誤り。','誤り。'],'BUTSU1'),
 ('P4-S02','P-BUN-KONGO',U1,1,'ツボ「灯油は、たった1種類の物質でできているのさ！」',['灯油はいくつもの炭化水素が混じった混合物','1種類の化合物','単体'],'ガソリン・灯油・軽油などの石油製品は混合物。',['正しい。','誤り。','誤り。'],'KAGAKU2'),
 ('P4-S03','P-BUN-TANTAI',U1,1,'ツボ「水は、水素という1つの元素だけでできた単体だよ！」',['水は水素と酸素が結びついた化合物','単体','混合物'],'2種類以上の元素が化学的に結びついた物は化合物。',['正しい。','誤り。','誤り。'],'BUTSU1'),
 ('P4-S04','P-BUN-DOUSOTAI',U1,1,'ツボ「ダイヤモンドと黒鉛は、元素がちがうんだ！」',['どちらも炭素だけでできた同素体','元素がちがう','混合物'],'同じ元素の、性質のちがう単体どうしが同素体。',['正しい。','誤り。','誤り。'],'BUTSU1'),
 ('P4-S05','P-GEN-HANNOU',U2,2,'カズアワズ・ハカセが黒板に式を書きなぐっている！「水素と酸素から水ができる式は、H₂＋O₂→H₂O で完成じゃ！」 ハカセが力を溜めている！',['原子の数がそろわない。正しくは 2H₂＋O₂→2H₂O','それで完成','H₂＋O₂→2H₂O'],'反応の前後で原子の数をそろえる。',['正しい。','O原子の数が合わない。','H原子の数が合わない。'],'KAGAKU2'),
 ('P4-S06','P-GEN-SHITSURYO',U2,2,'ハカセ「反応すると、全体の重さは減ってしまうのじゃ！」',['反応の前後で、物質全体の質量は変わらない（質量保存の法則）','減る','増える'],'化学反応では原子の組み合わせが変わるだけなので、全体の質量は変わらない。',['正しい。','誤り。','誤り。'],'KAGAKU2'),
 ('P4-S07','P-GEN-MOL',U2,2,'ハカセ「標準状態では、重い気体ほど1molの体積が大きいのじゃ！」',['どの気体も1molは約22.4L','重いほど大きい','軽いほど大きい'],'0℃・1気圧では、気体の種類によらず1molは約22.4L。',['正しい。','誤り。','誤り。'],'KAGAKU2'),
 ('P4-S08','P-GEN-BUNSHIRYO',U2,2,'ハカセ「水（H₂O）の分子量は、1＋16で17じゃ！」',['Hは2つなので、1×2＋16＝18','17','34'],'H＝1、O＝16。H₂Oは18。',['正しい。','Hが1つ分足りない。','誤り。'],'KAGAKU2'),
 ('P4-S09','P-SAN-TEIGI',U3,3,'サビツキ・ナイトがさびた剣を振り上げた！「酸化とは、酸素を失うことだ！」 ナイトが力を溜めている！',['酸化は酸素と化合すること。酸素を失うのは還元','酸素を失うこと','水素と化合すること'],'酸化と還元は逆の変化で、同時に起こる。',['正しい。','還元。','還元。'],'KAGAKU1'),
 ('P4-S10','P-SAN-ZAI',U3,3,'ナイト「酸化剤は、自分が酸化される物のことだ！」',['酸化剤は相手を酸化し、自分は還元される','自分が酸化される','何も変わらない'],'酸化剤は他の物質を酸化する（自身は還元される）。還元剤はその逆。',['正しい。','還元剤の性質。','誤り。'],'KAGAKU1'),
 ('P4-S11','P-ION-JUN',U3,3,'ナイト「金は、鉄よりもさびやすい金属だ！」',['金はイオン化傾向が最も小さく、さびにくい','金のほうがさびやすい','同じ'],'イオン化傾向が大きい金属ほど陽イオンになりやすく、腐食しやすい。',['正しい。','誤り。','誤り。'],'KAGAKU2'),
 ('P4-S12','P-ION-BOUSHOKU',U3,3,'ナイト「鉄の配管を守るには、銅の板をつなげばよい！」',['鉄よりイオン化傾向の大きい亜鉛やマグネシウムをつなぐ','銅をつなぐ','何もしない'],'銅のようにイオン化傾向の小さい金属をつなぐと、鉄が先に腐食する。',['正しい。','逆効果。','誤り。'],'KAGAKU2'),
 ('P4-S13','P-PH-SANSEI',U4,4,'スッパニガ・ゼリーがぷるぷるふるえている！「pHが7より大きいほど、酸性が強いのさ！」 ゼリーが力を溜めている！',['pHが7より小さいほど酸性が強い。大きいほど塩基性','7より大きいほど酸性','7が最も酸性'],'pH7が中性。小さいほど酸性、大きいほど塩基性（アルカリ性）。',['正しい。','逆。','中性。'],'KAGAKU2'),
 ('P4-S14','P-PH-ENKI',U4,4,'ゼリー「塩基の水溶液は、赤色リトマス紙を赤いままにするよ！」',['塩基性の水溶液は、赤色リトマス紙を青くする','赤いまま','白くする'],'酸は青→赤、塩基は赤→青。',['正しい。','誤り。','誤り。'],'KAGAKU2'),
 ('P4-S15','P-PH-CHUWA',U4,4,'ゼリー「酸と塩基をまぜると、もっと強い酸ができるのさ！」',['酸と塩基は中和して、塩と水ができる','もっと強い酸になる','酸素ができる'],'中和：酸＋塩基→塩＋水。',['正しい。','誤り。','誤り。'],'KAGAKU2'),
 ('P4-S16','P-YUU-TOKUCHO',U5,4,'ゼリー「ベンゼンのような有機化合物は、水によく溶けるよ！」',['水に溶けにくいものが多い','水によく溶ける','水と反応して燃える'],'有機化合物は水に溶けにくく、有機溶媒に溶けやすいものが多い。',['正しい。','誤り。','誤り。'],'BUTSU1'),
]:
    q(id,kid,topic,stage,S,t,ch,0,ex,ce,src=src,enemy=EN[stage],town=TP,subject='物理・化学')
